    const tip = `The room's comb: the amplitude-weighted mean of its modes, ${lit.toFixed(1)} Hz in the data.${folded ? ` SC folds it by octaves into 35–140 Hz, so you hear ${h.toFixed(1)} Hz.` : ""}`;
