    const fs = ident.modes.map(SvkCook.heardHz).filter((f) => f > 0), lo = Math.min(...fs) / 1.3, hi = Math.max(...fs) * 1.3;
    const xs = d3.scaleLog().domain([lo, hi]).range([6, W - 6]), ys = (a) => H - 12 - a * (H - 18);
